        for (int i = 0; i < k && kth != null; i++) kth = ___;
        if (kth == null) break;              // fewer than k nodes — leave them
        var groupNext = kth.next;
        ListNode prev = ___, cur = groupPrev.next;
        while (cur != groupNext) {
            var next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        var first = groupPrev.next;
