// order does not matter: O(1) removal without nodes
void RemoveAtSwapBack<T>(List<T> list, int i) {
    int last = list.Count - 1;
    list[i] = list[last];      // the last element takes the removed one's place
    list.RemoveAt(last);       // removing from the end shifts nothing
}

