public struct Node { public int value; public int next; }   // next = -1 — the end

public sealed class IndexList {
    Node[] nodes = new Node[16];
    int count;              // how many cells have ever been handed out
    int free = -1;          // head of the free list
    public int Head = -1;

    public int PushFront(int value) {
        int i;
        if (free != -1) { i = free; free = nodes[i].next; }   // reuse a cell
        else {
            if (count == nodes.Length) Array.Resize(ref nodes, count * 2);
            i = count++;
        }
        nodes[i] = new Node { value = value, next = Head };
        Head = i;
        return i;
    }
    public void PopFront() {
        int i = Head;
        Head = nodes[i].next;
        nodes[i].next = free; free = i;                        // the cell goes to the free list
    }
}
